PAPERS.update({
 'ilagan-2023-teaching-diffusion-abm': {'pdf': 'ilagan-2023-teaching-diffusion-abm.pdf', 'version': 'Accepted manuscript', 'date': '2023/07/09', 'book': 'Adaptive Instructional Systems', 'conference': 'HCI International 2023', 'series': 'Lecture Notes in Computer Science', 'firstpage': '298', 'lastpage': '311', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Agent-based modeling', 'Agent-based simulation modeling', 'Computer simulation', 'Entrepreneurship education', 'Diffusion of innovations'], 'abstract': 'Entrepreneurship education has traditionally been based on business management education, which has been ineffective in teaching the complex, dynamic, and non-linear nature of entrepreneurship. Recent attempts at entrepreneurship education have involved using computer simulations to reduce time and cost. One type of computer simulation, agent-based modeling and simulation (ABMS), takes into account the behaviors, reactions, and interactions of individual agents and has the potential to capture the behavior of a complex system, such as a market, more accurately than traditional approaches. This study proposes the use of ABMS in a technology entrepreneurship program to teach students about the theory of diffusion of innovations and how to implement various technology strategies, such as pursuing technology leadership or behaving as an early adopter. The simulation will involve a minimal model implemented using NetLogo and students will be able to explore different strategies and experience the advantages and drawbacks of each. The learning experience will be designed based on entrepreneurial process theories, learning by trying/emergence, learning from failure, bounded rationality, effectuation, entrepreneurial cognition, and entrepreneurial management and growth. The goal of the simulation is to provide students with an experiential and adaptive learning environment that allows them to understand as entrepreneurs how consumers adopt new innovations and receive feedback on their decisions. The user interface will show an animation of the model’s results and output, some of which include: the adoption curve, adopter profiles, and the social network.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-34735-1_21">http://dx.doi.org/10.1007/978-3-031-34735-1_21</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'ilagan-2024-conversational-commerce': {'pdf': 'ilagan-2024-conversational-commerce.pdf', 'version': 'Accepted manuscript', 'date': '2024/05/23', 'book': 'Artificial Intelligence in HCI', 'conference': 'HCI International 2024', 'series': 'Lecture Notes in Computer Science', 'firstpage': '47', 'lastpage': '59', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Conversational user experience', 'conversational commerce', 'Large language models', 'Natural language understanding', 'Named entity recognition', 'Generative AI', 'Co-pilots'], 'abstract': 'Due to the emergence of natural language processing (NLP) interfaces, there has been growing intent to use conversational channels for commerce. Beyond customer service, NLP-enabled AI agents are being integrated into various steps of the order-to-cash (OTC) process. Social media and messaging platforms such as Facebook Messenger have become pivotal for businesses, especially during and after the COVID-19 pandemic, but adoption has been limited. In addition, attitudes towards fully-automated conversational agents (CA) have been mixed, and there is room for human involvement in transactional conversations. A distinguishing contribution of this research is leveraging the inherent capabilities of Large Language Models (LLMs) in handling multilingual conversations and extracting transactional details through named entity recognition (NER). The study describes a hybrid human-AI setup augmenting agents with an auto-agent leveraging LLMs’ natural language understanding (NLU) capabilities, designed using the OTC process pattern applied to conversational UX frameworks. A prototype of the setup aims to streamline operations and reduce errors by enhancing the user experience during key OTC steps through improved conversational design. Recognizing the irreplaceable essence of human interaction, the hybrid human-in-the-loop approach was chosen, mitigating the impersonal nature of full automation. A prototype handling customers and humans augmented by LLMs for NER handling of transaction, customer, and product information was built. Sample synthetic bilingual conversations between customers and sales agents were generated using ChatGPT and fed into the system for evaluation.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-60615-1_4">http://dx.doi.org/10.1007/978-3-031-60615-1_4</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'ilagan-2025-financial-modeling-mentor': {'pdf': 'ilagan-2025-financial-modeling-mentor.pdf', 'version': 'Accepted manuscript', 'date': '2025/05/25', 'book': 'Adaptive Instructional Systems', 'conference': 'HCI International 2025', 'series': 'Lecture Notes in Computer Science', 'firstpage': '56', 'lastpage': '66', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Entrepreneurship education', 'Generative AI', 'Agentic systems', 'Tutoring Chatbot', 'Chatbot'], 'abstract': 'Entrepreneurship education (EE) aims to deliver various entrepreneurial outcomes. One such entrepreneurial outcome (EO) is entrepreneurial intent (EI), which has been touted as one of the most significant determinants of a new business. Entrepreneurial mentoring (EM) has been linked and indirectly measured for its relationship with improved EO and EI. In countries in the Global South, such as the Philippines, there are only a few qualified instructors and mentors for entrepreneurship. Due to the lack of qualified faculty to do mentoring in universities, this study aims to turn to computer-based alternatives to address the under-resourcing of qualified human faculty. This study introduces an approach using Generative AI (GAI) and Large Language Models (LLMs) to simulate startup modeling mentoring to enhance EE by bridging these gaps. The coaching experience is intended to be contextual and adaptive based on the student’s input and interactions. An area of mentorship is financial modeling as a replacement for traditional financial forecasting methods. Using the Business Model Canvas (BMC) framework, the proposed simulator employs natural language processing (NLP) to offer real-time feedback and support to student startups. This research evaluates the impact of these simulations on learning efficacy, satisfaction, and entrepreneurial intent. It proposes a pre and post-test quasi-experimental design during implementation with live participants iteratively across several school semesters. However, before the sessions with humans, the study can already make preliminary tests using GAI agents as simulated personas during development. Once implemented, the findings may provide insight into the potential of simulated mentoring as a scalable and effective educational tool in entrepreneurship, offering significant insights into integrating AI technologies in enhancing entrepreneurial learning environments.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-92967-0_4">http://dx.doi.org/10.1007/978-3-031-92967-0_4</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'alabastro-2025-applied-ocr-llm': {'pdf': 'alabastro-2025-applied-ocr-llm.pdf', 'version': 'Accepted manuscript', 'date': '2025/05/30', 'book': 'Artificial Intelligence in HCI', 'conference': 'HCI International 2025', 'series': 'Lecture Notes in Computer Science', 'firstpage': '267', 'lastpage': '276', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Optical character recognition', 'artificial intelligence', 'large language models', 'Python', 'data engineering', 'AI', 'prompt engineering', 'food stalls', 'local enterprises', 'sales analytics', 'staff augmentation'], 'abstract': 'The local business landscape in the Philippines presents a slow adoption to digitization. There are fears of inaccurate results and limited technical proficiency. Data analytics and artificial intelligence (AI) are crucial for business growth. By understanding the performance of stock-keeping-units (SKU) with technology, businesses can find better ways to handle products to increase profitability. In exploring optical character recognition (OCR) and large language models (LLM), a software pipeline can help businesses analyze handwritten sales data for business intelligence. The research aims to develop a system for translating logbooks into metrics by augmenting manual business processes performed by staff. The application combines Amazon Web Services’ OCR technology with Anthropic’s Haiku 3.0 LLM. The pipeline extracts handwritten text from images and performs few-shot learning-based classification. Data from a local food stall was used for testing. Precision and recall scores were calculated to analyze similarities between original and extracted data. Results showed moderate-low precision but above-average recall. The SKUs yielded average precision and recall scores of 0.32 and 0.62, while sales data stood at 0.55 and 0.54, respectively. These scores indicate that the application struggles with accuracy but captures a fair amount of true values. Improvements are needed to enhance the learning mechanism of the LLM. Despite this, the application holds promise for helping small businesses achieve digitization to supplement manual business processes, taking into account the limited technological literacy of staff. It serves as a potential catalyst for growth by simplifying complex data problems with cost-efficient solutions.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-93429-2_18">http://dx.doi.org/10.1007/978-3-031-93429-2_18</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'ilagan-2025-virtual-support-agent': {'pdf': 'ilagan-2025-virtual-support-agent.pdf', 'version': 'Accepted manuscript', 'date': '2025/05/30', 'book': 'Artificial Intelligence in HCI', 'conference': 'HCI International 2025', 'series': 'Lecture Notes in Computer Science', 'firstpage': '253', 'lastpage': '262', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Conversational UX', 'Large language models', 'LLM', 'RAG', 'Chatbots', 'University chatbots', 'Generative AI', 'GenAI'], 'abstract': 'This paper presents a pilot study of a university virtual support agent system powered by a Large Language Model (LLM) engineered to address student inquiries regarding processes and policies involving a student exchange program. Traditional approaches to implementing chatbots in university student support services have had their shortcomings. This study investigates the enablement of conversational support using generative artificial intelligence and natural conversation properties inherent in LLMs and how they may overcome such shortcomings from earlier attempts at conversational support. The LLMs’ susceptibility to ‘hallucination’ is mitigated through a combined approach of few-shot learning, retrieval augmented generation (RAG), and chain of thought (CoT) libraries in the training phase. The system utilizes OpenAI’s GPT-4o model behind a Python-based web framework, enabling the conversational interface used by the students. The information system is grounded in earlier email correspondences from program heads to students, PDF files containing primers, and other sources. The pilot implementation of the system involves an outbound student exchange program in a private university in the Philippines. Sophomore students were invited to test and evaluate the system and interviewed after the chatbot sessions.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-93415-5_15">http://dx.doi.org/10.1007/978-3-031-93415-5_15</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'to-2025-augmenting-customer-validation': {'pdf': 'to-2025-augmenting-customer-validation.pdf', 'version': 'Accepted manuscript', 'date': '2025/05/26', 'book': 'HCI in Business, Government and Organizations', 'conference': 'HCI International 2025', 'series': 'Lecture Notes in Computer Science', 'firstpage': '209', 'lastpage': '220', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Large language models', 'artificial intelligence', 'natural language processing', 'continuous learning', 'LLM adaptive coaching', 'LLM simulation', 'customer development', 'entrepreneurship'], 'abstract': 'Startup founders experience numerous barriers to venture creation. Customer development (CD), under the Lean Startup (LS) methodology, is a customer-centric process of refining business models to reduce startup failure. This paper explores the design of an LLM-based, adaptive coaching model that utilizes artificial intelligence’s (AI) natural language processing (NLP) and continuous learning capabilities to formulate contextual responses that are suitable for the user’s business context. Subsequently, the model generates synthetic customer insights to simulate customer interactions and strengthen CD competencies, creating more efficient systems for startup validation. Results suggest that the LLM-based adaptive coaching model is effective for startup validation and entrepreneurial education.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-031-92823-9_14">http://dx.doi.org/10.1007/978-3-031-92823-9_14</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'uy-2026-ai-driven-adaptive-simulations': {'pdf': 'uy-2026-ai-driven-adaptive-simulations.pdf', 'version': 'Accepted manuscript', 'date': '2026/07/02', 'book': 'HCI International 2026 Posters', 'conference': 'HCI International 2026', 'series': 'Communications in Computer and Information Science', 'firstpage': '153', 'lastpage': '162', 'publisher': 'Springer Nature Switzerland', 'keywords': ['Artificial intelligence in education', 'Adaptive learning', 'Educational simulators', 'Simulation-based learning', 'Management education', 'Student engagement', 'Philippine higher education'], 'abstract': 'This paper reports an exploratory classroom deployment study of instructor-authored AI-generated business simulations used in undergraduate management education at a Philippine higher education institution. Using an in-house developed natural-language, chat-based simulator authoring interface, instructors generated lesson-specific simulations aligned with course objectives, refined them within the same interface, and deployed them to students through a shared web link. During classroom use, the simulation implemented a bounded, within-session form of adaptivity in which student decisions shaped subsequent scenario conditions, feedback, and later developments in the activity. The simulation was deployed across four undergraduate courses. Data collection used a pre-session/post-session survey design, yielding 82 pre-session responses, 70 post-session responses, and 68 matched response pairs, alongside open-ended post-session reflections. Students evaluated the simulation positively in terms of applied learning, engagement with evolving scenarios, and overall classroom experience. Matched responses also showed higher post-session self-ratings in understanding, application, confidence, reasoning, and preparedness. Qualitative responses suggest that the simulation’s perceived value was tied to realistic framing, visible consequences of decisions, and the need to respond to changing conditions. Pacing, instructional clarity, and technical reliability also emerged as important implementation conditions. The study contributes exploratory evidence on how a decision-contingent, instructor-authored adaptive system was experienced in authentic classroom use within Philippine higher education.', 'notice': 'This version of the contribution has been accepted for publication, after peer review (when applicable) but is not the Version of Record and does not reflect post-acceptance improvements, or any corrections. The Version of Record is available online at: <a href="http://dx.doi.org/10.1007/978-3-032-30833-7_17">http://dx.doi.org/10.1007/978-3-032-30833-7_17</a>. Use of this Accepted Version is subject to the publisher’s Accepted Manuscript terms of use <a href="https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms">https://www.springernature.com/gp/open-research/policies/accepted-manuscript-terms</a>'},
 'alabastro-2025-collaborative-product-innovation': {'pdf': 'alabastro-2025-collaborative-product-innovation-preprint.pdf', 'version': 'Preprint (version submitted for peer review)', 'date': '2025/10/08', 'book': 'Proceedings of Tenth International Congress on Information and Communication Technology', 'conference': 'ICICT 2025', 'series': 'Lecture Notes in Networks and Systems', 'firstpage': '271', 'lastpage': '281', 'publisher': 'Springer Nature Singapore', 'keywords': ['product innovation', 'qualitative customer feedback', 'ChatGPT-4o', 'agentic AI systems', 'homo silicus', 'large language model', 'few-shot inferencing', 'cosine similarity'], 'abstract': 'Product innovation is critical in strategizing business decisions in highly-competitive markets. For product enhancements, the entrepreneur must garner data from a target demographic through research. A solution to this involves qualitative customer feedback. The study proposes the viability of artificial intelligence (AI) as a co-pilot model to simulate synthetic customer feedback with agentic systems. Prompting with ChatGPT-4o’s homo silicus attribute can generate feedback on certain business contexts. Results show that large language models (LLM) can generate qualitative insights to utilize in product innovation. Results seem to generate human-like responses through few-shot techniques and Chain-of-Thought (CoT) prompting. Data was validated with a Python script. Cosine similarity tested the similarity of datasets to quantify the juxtaposition of synthetic and actual customer feedback. This model can be essential in reducing the total resources needed for product evaluation through preliminary analysis, which can help in sustainable competitive advantage.', 'notice': 'This is a preprint of the following chapter: Zachary Matthew Alabastro, Stephen Daeniel Mansueto, Joseph Benjamin Ilagan, Collaborative Product Innovation Model with Large Language Models and Agentic Systems, published in Proceedings of Tenth International Congress on Information and Communication Technology (ICICT 2025), edited by Xin-She Yang, R. Simon Sherratt, Nilanjan Dey, Amit Joshi, 2025, Springer reproduced with permission of Springer Nature Singapore Pte Ltd. The final authenticated version is available online at: <a href="http://dx.doi.org/10.1007/978-981-96-6938-7_23">http://dx.doi.org/10.1007/978-981-96-6938-7_23</a>'},
})

PAPERS['ilagan-2026-draft-only-never-send'] = {'pdf': 'ilagan-2026-draft-only-never-send.pdf', 'version': 'Accepted manuscript', 'date': '2026', 'journal': 'IEEE Software', 'firstpage': '1', 'lastpage': '7', 'publisher': 'IEEE', 'pubshort': 'IEEE', 'keywords': ['agentic workflows', 'AI hardening', 'agent harness', 'multi-model routing', 'LLM deployment', 'software engineering practice'], 'abstract': 'AI-assisted workflows often start as open-ended prompting and end up as deterministic scripts. This report describes that shift in two workflows we built in a small university lab in early 2026: a geospatial classification pipeline over about 3,000 establishment records, and a reimbursement workflow that once sent an email we did not mean to send. One hardened because of cost, the other because of risk, but both the same way: we used a capable model to write explicit checks and guardrails, then let cheaper models or plain scripts run inside them. In software-engineering terms, the result is an execution harness around an unreliable component. That construct is old news. What we think is worth reporting is how the harness came together after the fact, in a lab that never meant to build one, and which failures are specific to a multi-model setup, where knowing which model actually acted matters for forensics and is almost never logged.', 'notice': '© 2026 IEEE. Personal use of this material is permitted. Permission from IEEE must be obtained for all other uses, in any current or future media, including reprinting/republishing this material for advertising or promotional purposes, creating new collective works, for resale or redistribution to servers or lists, or reuse of any copyrighted component of this work in other works. This is the accepted manuscript of an article accepted for publication in <i>IEEE Software</i>. The final version is available at <a href="https://doi.org/10.1109/MS.2026.3716868">https://doi.org/10.1109/MS.2026.3716868</a>.'}
